import React from 'react';
import { Link } from 'react-router-dom';

export default function ContactModal({ item, onClose }) {
  if (!item) return null;
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <h3>📞 Contact Reporter</h3>
        <p><strong>Item:</strong> {item.title} ({item.category})</p>
        <p><strong>Reported by:</strong> {item.user?.fullName}</p>
        <p><strong>Email:</strong> <a href={`mailto:${item.user?.email}`}>{item.user?.email}</a></p>
        <p><strong>Phone:</strong> <a href={`tel:${item.user?.phone}`}>{item.user?.phone}</a></p>
        <p><strong>Location:</strong> 📍 {item.location}</p>
        <p><strong>Date:</strong> {new Date(item.date).toLocaleDateString()}</p>
        <div className="modal-actions">
          <button className="btn btn-outline btn-sm" onClick={onClose}>Close</button>
          <Link to={`/item/${item._id}`} className="btn btn-green btn-sm" onClick={onClose}>
            View Full Details
          </Link>
        </div>
      </div>
    </div>
  );
}
